fn main() -> Result<(), String> {
    let sdl_context = sdl2::init()?;
    let video_subsystem = sdl_context.video()?;

    let window = video_subsystem
        .window(
            "Tetris",
            BOARD_OFFSET_X + BOARD_WIDTH as u32 * CELL_SIZE + 200,
            BOARD_OFFSET_Y + BOARD_HEIGHT as u32 * CELL_SIZE + 20,
        )
        .position_centered()
        .opengl()
        .build()
        .map_err(|e| e.to_string())?;

    let mut canvas = window.into_canvas()
        .target_texture()
        .present_vsync()
        .build()
        .map_err(|e| e.to_string())?;

    canvas.set_draw_color(Color::RGB(20, 20, 30));
    canvas.clear();
    canvas.present();

    let mut event_pump = sdl_context.event_pump()?;

    let mut game = Game::new();
    let mut last_drop_time = std::time::Instant::now();

    'running: loop {
        for event in event_pump.poll_iter() {
            match event {
                Event::Quit { .. } => break 'running,
                Event::KeyDown { keycode: Some(keycode), .. } => {
                    if game.game_over {
                        if keycode == Keycode::R {
                            game = Game::new();
                            last_drop_time = std::time::Instant::now();
                        }
                        continue;
                    }

                    match keycode {
                        Keycode::Left => {
                            game.move_piece(-1, 0);
                        }
                        Keycode::Right => {
                            game.move_piece(1, 0);
                        }
                        Keycode::Down => {
                            if game.move_piece(0, 1) {
                                game.score += 1; // Soft drop bonus
                            }
                        }
                        Keycode::Up | Keycode::X => {
                            game.rotate_piece(true);
                        }
                        Keycode::Z => {
                            game.rotate_piece(false);
                        }
                        Keycode::Space => {
                            game.hard_drop();
                        }
                        Keycode::Escape => break 'running,
                        _ => {}
                    }
                }
                _ => {}
            }
        }

        // Auto drop
        if !game.game_over {
            let elapsed = last_drop_time.elapsed();
            if elapsed >= Duration::from_millis(game.drop_interval) {
                if !game.drop_piece() {
                    game.lock_piece();
                }
                last_drop_time = std::time::Instant::now();
            }
        }

        draw_board(&mut canvas, &game);
        canvas.present();

        // Cap at ~60 FPS
        std::thread::sleep(Duration::from_millis(16));
    }

    Ok(())
}
