impl Game {
    fn new() -> Self {
        let mut rng = rand::thread_rng();
        Game {
            board: [[None; BOARD_WIDTH]; BOARD_HEIGHT],
            current_piece: Piece::new(rng.gen_range(0..7)),
            next_piece: Piece::new(rng.gen_range(0..7)),
            score: 0,
            lines_cleared: 0,
            level: 1,
            game_over: false,
            drop_interval: 1000,
        }
    }

    fn is_valid_position(&self, piece: &Piece, offset_x: i32, offset_y: i32) -> bool {
        let blocks = piece.get_blocks();
        for (bx, by) in blocks.iter() {
            let new_x = piece.x + bx + offset_x;
            let new_y = piece.y + by + offset_y;

            if new_x < 0 || new_x >= BOARD_WIDTH as i32 {
                return false;
            }
            if new_y >= BOARD_HEIGHT as i32 {
                return false;
            }
            if new_y >= 0 && self.board[new_y as usize][new_x as usize].is_some() {
                return false;
            }
        }
        true
    }

    fn move_piece(&mut self, dx: i32, dy: i32) -> bool {
        if self.is_valid_position(&self.current_piece, dx, dy) {
            self.current_piece.x += dx;
            self.current_piece.y += dy;
            true
        } else {
            false
        }
    }

    fn rotate_piece(&mut self, clockwise: bool) {
        let mut test_piece = self.current_piece.clone();
        test_piece.rotate(clockwise);

        // Try basic rotation
        if self.is_valid_position(&test_piece, 0, 0) {
            self.current_piece = test_piece;
            return;
        }

        // Wall kick - try offsetting left/right
        for offset in [-1, 1, -2, 2].iter() {
            if self.is_valid_position(&test_piece, *offset, 0) {
