            self.score += 2; // Bonus for hard drop
        }
        self.lock_piece();
    }
}

fn draw_board(canvas: &mut Canvas<Window>, game: &Game) {
    // Clear screen
    canvas.set_draw_color(Color::RGB(20, 20, 30));
