use rand::Rng;
use sdl2::event::Event;
use sdl2::keyboard::Keycode;
use sdl2::pixels::Color;
use sdl2::rect::Rect;
use sdl2::render::Canvas;
use sdl2::video::Window;
use std::time::Duration;

// Game constants
const BOARD_WIDTH: usize = 10;
const BOARD_HEIGHT: usize = 20;
const CELL_SIZE: u32 = 30;
const BOARD_OFFSET_X: u32 = 50;
const BOARD_OFFSET_Y: u32 = 50;

// Tetromino shapes - each piece has 4 rotation states, each with 4 blocks
const SHAPES: [[[[(i32, i32); 4]; 4]; 7]; 4] = [
    // I piece rotations
    [
        [(0, 1), (1, 1), (2, 1), (3, 1)],
        [(2, 0), (2, 1), (2, 2), (2, 3)],
        [(0, 2), (1, 2), (2, 2), (3, 2)],
        [(1, 0), (1, 1), (1, 2), (1, 3)],
    ],
    // O piece rotations
    [
        [(1, 0), (2, 0), (1, 1), (2, 1)],
        [(1, 0), (2, 0), (1, 1), (2, 1)],
        [(1, 0), (2, 0), (1, 1), (2, 1)],
        [(1, 0), (2, 0), (1, 1), (2, 1)],
    ],
    // T piece rotations
    [
        [(1, 0), (0, 1), (1, 1), (2, 1)],
        [(1, 0), (1, 1), (2, 1), (1, 2)],
        [(0, 1), (1, 1), (2, 1), (1, 2)],
        [(1, 0), (0, 1), (1, 1), (1, 2)],
    ],
    // S piece rotations
    [
        [(1, 0), (2, 0), (0, 1), (1, 1)],
        [(1, 0), (1, 1), (2, 1), (2, 2)],
        [(1, 1), (2, 1), (0, 2), (1, 2)],
        [(0, 0), (0, 1), (1, 1), (1, 2)],
    ],
    // Z piece rotations
    [
        [(0, 0), (1, 0), (1, 1), (2, 1)],
        [(2, 0), (1, 1), (2, 1), (1, 2)],
        [(0, 1), (1, 1), (1, 2), (2, 2)],
        [(1, 0), (0, 1), (1, 1), (0, 2)],
    ],
    // J piece rotations
    [
        [(0, 0), (0, 1), (1, 1), (2, 1)],
        [(1, 0), (2, 0), (1, 1), (1, 2)],
        [(0, 1), (1, 1), (2, 1), (2, 2)],
        [(1, 0), (1, 1), (0, 2), (1, 2)],
    ],
    // L piece rotations
    [
        [(2, 0), (0, 1), (1, 1), (2, 1)],
        [(1, 0), (1, 1), (1, 2), (2, 2)],
        [(0, 1), (1, 1), (2, 1), (0, 2)],
        [(0, 0), (1, 0), (1, 1), (1, 2)],
    ],
];

// Colors for each piece type
const COLORS: [Color; 7] = [
    Color::RGB(0, 255, 255),   // I - Cyan
    Color::RGB(255, 255, 0),   // O - Yellow
    Color::RGB(128, 0, 128),   // T - Purple
    Color::RGB(0, 255, 0),     // S - Green
    Color::RGB(255, 0, 0),     // Z - Red
    Color::RGB(0, 0, 255),     // J - Blue
    Color::RGB(255, 128, 0),   // L - Orange
];

#[derive(Clone, Copy)]
struct Piece {
    shape_idx: usize,
    rotation: usize,
    x: i32,
    y: i32,
}

impl Piece {
    fn new(shape_idx: usize) -> Self {
        Piece {
            shape_idx,
            rotation: 0,
            x: 3,
            y: 0,
        }
    }

    fn get_blocks(&self) -> [(i32, i32); 4] {
        SHAPES[self.rotation][self.shape_idx][self.rotation]
    }

    fn rotate(&mut self, clockwise: bool) {
        if clockwise {
            self.rotation = (self.rotation + 1) % 4;
        } else {
            self.rotation = (self.rotation + 3) % 4;
        }
    }
}

struct Game {
    board: [[Option<usize>; BOARD_WIDTH]; BOARD_HEIGHT],
    current_piece: Piece,
    next_piece: Piece,
    score: u32,
    lines_cleared: u32,
    level: u32,
    game_over: bool,
    drop_interval: u64,
}

impl Game {
    fn new() -> Self {
        let mut rng = rand::thread_rng();
        Game {
            board: [[None; BOARD_WIDTH]; BOARD_HEIGHT],
            current_piece: Piece::new(rng.gen_range(0..7)),
            next_piece: Piece::new(rng.gen_range(0..7)),
            score: 0,
            lines_cleared: 0,
            level: 1,
            game_over: false,
            drop_interval: 1000,
        }
    }

    fn is_valid_position(&self, piece: &Piece, offset_x: i32, offset_y: i32) -> bool {
        let blocks = piece.get_blocks();
        for (bx, by) in blocks.iter() {
            let new_x = piece.x + bx + offset_x;
            let new_y = piece.y + by + offset_y;

            if new_x < 0 || new_x >= BOARD_WIDTH as i32 {
                return false;
            }
            if new_y >= BOARD_HEIGHT as i32 {
                return false;
            }
            if new_y >= 0 && self.board[new_y as usize][new_x as usize].is_some() {
                return false;
            }
        }
        true
    }

    fn move_piece(&mut self, dx: i32, dy: i32) -> bool {
        if self.is_valid_position(&self.current_piece, dx, dy) {
            self.current_piece.x += dx;
            self.current_piece.y += dy;
            true
        } else {
            false
        }
    }

    fn rotate_piece(&mut self, clockwise: bool) {
        let mut test_piece = self.current_piece.clone();
        test_piece.rotate(clockwise);

        // Try basic rotation
        if self.is_valid_position(&test_piece, 0, 0) {
            self.current_piece = test_piece;
            return;
        }

        // Wall kick - try offsetting left/right
        for offset in [-1, 1, -2, 2].iter() {
            if self.is_valid_position(&test_piece, *offset, 0) {
                test_piece.x += *offset;
                self.current_piece = test_piece;
                return;
            }
        }
    }

    fn drop_piece(&mut self) -> bool {
        self.move_piece(0, 1)
    }

    fn lock_piece(&mut self) {
        let blocks = self.current_piece.get_blocks();
        for (bx, by) in blocks.iter() {
            let x = (self.current_piece.x + bx) as usize;
            let y = (self.current_piece.y + by) as usize;
            if y < BOARD_HEIGHT {
                self.board[y][x] = Some(self.current_piece.shape_idx);
            }
        }

        self.clear_lines();
        self.current_piece = self.next_piece;
        let mut rng = rand::thread_rng();
        self.next_piece = Piece::new(rng.gen_range(0..7));

        if !self.is_valid_position(&self.current_piece, 0, 0) {
            self.game_over = true;
        }
    }

    fn clear_lines(&mut self) {
        let mut lines_to_clear = Vec::new();

        for y in 0..BOARD_HEIGHT {
            if self.board[y].iter().all(|cell| cell.is_some()) {
                lines_to_clear.push(y);
            }
        }

        let num_lines = lines_to_clear.len();
        if num_lines > 0 {
            // Remove cleared lines and shift down - manual array manipulation
            let mut new_board = [[None; BOARD_WIDTH]; BOARD_HEIGHT];
            let mut new_y = 0;

            for y in 0..BOARD_HEIGHT {
                if !lines_to_clear.contains(&y) {
                    new_board[new_y] = self.board[y];
                    new_y += 1;
                }
            }
            // Fill top rows with empty
            for y in new_y..BOARD_HEIGHT {
                new_board[y] = [None; BOARD_WIDTH];
            }

            self.board = new_board;

            self.lines_cleared += num_lines as u32;

            // Score calculation
            let line_scores = [0, 100, 300, 500, 800];
            self.score += line_scores[num_lines] * self.level;

            // Level up every 10 lines
            self.level = (self.lines_cleared / 10) + 1;
            self.drop_interval = std::cmp::max(100u64, (1000 - (self.level - 1) * 100) as u64);
        }
    }

    fn hard_drop(&mut self) {
        while self.move_piece(0, 1) {
            self.score += 2; // Bonus for hard drop
        }
        self.lock_piece();
    }
}

