    canvas.fill_rect(Rect::new(panel_x + 10, score_y + 50, 100, 15)).unwrap(); // Level label
    canvas.fill_rect(Rect::new(panel_x + 10, score_y + 75, 40, 15)).unwrap(); // Level value
